import { isAbsolute, resolve } from 'node:path';
import { validateHeaderName } from 'node:http';

const SCHEMA = 'stellar-forge.upstream-operation-ticket.v1';
const MAX_BYTES = 16384;
const HASH = /^[a-f0-9]{64}$/;
// These headers belong to HTTP, original payment/identity handling, or SF98.
const PROTECTED_HEADER = /^(?:host$|connection$|keep-alive$|te$|trailer$|upgrade$|expect$|content-|transfer-|accept$|accept-|authorization$|cookie$|set-cookie$|x-api-key$|api-key$|apikey$|proxy-|forwarded$|x-forwarded-|sec-|payment-|x-payment|x402-|extension-responses$|settlement-overrides$|x-sf98-order-id$)/;
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);

export class OperationTicketError extends Error {
  constructor(code) {
    super(code); this.name = 'OperationTicketError'; this.code = code;
    this.paymentSent = false;
  }
}
const need = (ok, code) => { if (!ok) throw new OperationTicketError(code); };

/** Validate only the private reference. Configuration never contains the bearer. */
export function operationTicketReference(operation) {
  const {ticketFile, ticketHeader} = operation;
  if (ticketFile === undefined) {
    need(ticketHeader === undefined, 'OPERATION_TICKET_FILE_REQUIRED');
    return null;
  }
  need(typeof ticketFile === 'string' && isAbsolute(ticketFile) &&
    !ticketFile.includes('\0') && resolve(ticketFile) === ticketFile,
    'OPERATION_TICKET_CANONICAL_PATH_REQUIRED');
  need((operation.method ?? 'GET') === 'POST', 'OPERATION_TICKET_POST_REQUIRED');
  const requestHeader = ticketHeader ?? 'x-merchant-operation';
  need(typeof requestHeader === 'string' && requestHeader.length >= 1 &&
    requestHeader.length <= 128 && requestHeader === requestHeader.toLowerCase(),
    'OPERATION_TICKET_HEADER_INVALID');
  try { validateHeaderName(requestHeader); }
  catch { throw new OperationTicketError('OPERATION_TICKET_HEADER_INVALID'); }
  need(!PROTECTED_HEADER.test(requestHeader) &&
    !Object.keys(operation.headers ?? {}).some(name => name.toLowerCase() === requestHeader),
    'OPERATION_TICKET_HEADER_RESERVED');
  return {file:ticketFile, requestHeader};
}

/** Bounded, same-owner, private regular file with no symlink aliases. */
async function privateBytes(path) {
  let handle;
  try {
    need(process.platform !== 'win32', 'OPERATION_TICKET_PRIVATE_POSIX_FILE_REQUIRED');
    need(await realpath(path) === path, 'OPERATION_TICKET_SYMLINK_REFUSED');
    handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
    const info = await handle.stat();
    need(info.isFile() && (info.mode & 0o077) === 0 &&
      (typeof process.getuid !== 'function' || info.uid === process.getuid()),
      'OPERATION_TICKET_PRIVATE_FILE_REQUIRED');
    need(info.size > 0 && info.size <= MAX_BYTES, 'OPERATION_TICKET_FILE_TOO_LARGE');
    const buffer = Buffer.alloc(MAX_BYTES + 1);
    let size = 0;
    while (size < buffer.length) {
      const {bytesRead} = await handle.read(buffer, size, buffer.length - size, size);
      if (!bytesRead) break;
      size += bytesRead;
    }
    need(size <= MAX_BYTES, 'OPERATION_TICKET_FILE_TOO_LARGE');
    return buffer.subarray(0, size);
  } catch (error) {
    if (error instanceof OperationTicketError) throw error;
    throw new OperationTicketError(error?.code === 'ENOENT' ?
      'OPERATION_TICKET_FILE_MISSING' : 'OPERATION_TICKET_FILE_UNREADABLE');
  } finally { if (handle) await handle.close(); }
}

export function requireCurrentOperationTicket(ticket, now = Date.now()) {
  if (ticket) need(ticket.expiresAt > now, 'OPERATION_TICKET_EXPIRED');
}

/** Read the merchant envelope without pretending to verify its private HMAC. */
export async function loadOperationTicket(operation, {requireCurrent = false} = {}) {
  const reference = operationTicketReference(operation);
  if (!reference) return null;
  const raw = await privateBytes(reference.file);
  return parseOperationTicketBytes(raw, operation, {requireCurrent});
}

/** The same envelope validation for a private transfer before creating files. */
export function parseOperationTicketBytes(raw, operation, {requireCurrent = false} = {}) {
  const reference = operationTicketReference(operation);
  need(reference && raw instanceof Uint8Array && raw.byteLength > 0 && raw.byteLength <= MAX_BYTES,
    'OPERATION_TICKET_SCHEMA_INVALID');
  raw = Buffer.from(raw);
  let value;
  try { value = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
  catch { throw new OperationTicketError('OPERATION_TICKET_JSON_INVALID'); }
  need(object(value) && Object.keys(value).length === 5 &&
    Object.keys(value).every(name => ['schema','ticket','operationKey','requestHash','expiresAt'].includes(name)) &&
    value.schema === SCHEMA && typeof value.ticket === 'string' && value.ticket.length <= 4096 &&
    /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]{43}$/.test(value.ticket) &&
    typeof value.operationKey === 'string' && HASH.test(value.operationKey) &&
    typeof value.requestHash === 'string' && HASH.test(value.requestHash) &&
    Number.isSafeInteger(value.expiresAt) && value.expiresAt > 0,
    'OPERATION_TICKET_SCHEMA_INVALID');
  const result = {schema:SCHEMA, operationKey:value.operationKey,
    requestHash:value.requestHash, expiresAt:value.expiresAt,
    requestHeader:reference.requestHeader,
    sha256:createHash('sha256').update(raw).digest('hex'), bytes:raw.length};
  // Accidental JSON/spread output remains metadata-only. Only request assembly
  // and private file copying access these two non-enumerable values.
  Object.defineProperties(result, {
    headerValue:{value:value.ticket}, sourceBytes:{value:raw},
  });
  if (requireCurrent) requireCurrentOperationTicket(result);
  return Object.freeze(result);
}

/** Safe for offline CLI/queue records. No ticket bytes, bearer, or HMAC key. */
export function operationTicketView(ticket) {
  return ticket ? {...ticket, expired:ticket.expiresAt <= Date.now()} : null;
}

/** The ordinary merchant header follows original SF31's unsigned + paid call. */
export function operationTicketHeaders(operation, ticket) {
  if (!ticket) return operation.headers;
  const reference = operationTicketReference(operation);
  need(reference?.requestHeader === ticket.requestHeader, 'OPERATION_TICKET_HEADER_CHANGED');
  return {...operation.headers, [ticket.requestHeader]:ticket.headerValue};
}

/** The queue pins the exact private file and rechecks it at execution entry. */
export function requireOperationTicketFingerprint(ticket, expected) {
  if (expected !== undefined)
    need((ticket?.sha256 ?? null) === expected, 'OPERATION_TICKET_SNAPSHOT_CHANGED');
}

// MIT. Merchant choices around the existing SF30 native stream policy.
import { compileUpstreamStreamPolicy } from '../../sf30-seller-sdk/upstream-stream.mjs';
import { DEFAULT_MAX_STREAM_BYTES } from '../../sf30-seller-sdk/stream-response.mjs';

const own = (value, key) => Object.hasOwn(value, key);
export const isMerchantStream = format => format === 'sse' || format === 'ndjson';

export function merchantPaymentRequirements(payment, amount) {
  const {paymentFlow, ...terms} = payment;
  if (own(payment, 'paymentFlow') && !['authorization', 'upfront'].includes(paymentFlow))
    throw new TypeError('Select authorization or upfront payment flow');
  return {scheme:'exact', ...terms, amount,
    ...(paymentFlow === undefined ? {} : {extra:{paymentFlow}})};
}

export function merchantStreamPolicy(row, method) {
  const format = row.responseMode ?? 'json';
  if (!['json', 'bytes', 'sse', 'ndjson'].includes(format))
    throw new TypeError('Select JSON, bytes, SSE or NDJSON response format');
  if (!isMerchantStream(format)) {
    if (own(row, 'stream')) throw new TypeError('Stream limits require SSE or NDJSON response format');
    return null;
  }
  if (method === 'HEAD') throw new TypeError('A HEAD response cannot carry a stream');
  if (own(row, 'cache') || own(row, 'idempotency'))
    throw new TypeError('Streaming uses one source per paid request; shared reads and durable POST responses require a complete response');
  if (row.responseValidation === 'declared' || row.enforceResponseContract === true)
    throw new TypeError('Streaming validates the declared media type and native framing; whole-response JSON validation requires JSON format');
  const policy = compileUpstreamStreamPolicy(row.stream, format);
  if (policy.maxBytes > DEFAULT_MAX_STREAM_BYTES)
    throw new TypeError('The compiled merchant stream limit is at most ' + DEFAULT_MAX_STREAM_BYTES + ' bytes');
  return policy;
}

#!/usr/bin/env python3
"""Fixed native DuckDB reader for an immutable SF30 operator declaration.

Derived from the released Commons DuckDB worker blob
25642b663cdb47f9afd3e2acca3be8d6ae70ad3d; MIT. The parent owns typed admission,
the wall-clock deadline and process slots. This worker has no HTTP or payments.
"""
from __future__ import annotations
import argparse
import base64
import datetime
import decimal
import json
import math
import os
import re
import sys
from pathlib import Path

SCHEMA = "stellar-forge.duckdb-source.v1"
NAME = re.compile(r"^[A-Za-z][A-Za-z0-9_]{0,47}$")
SAFE_ERRORS = {"CONFIG_INVALID", "DUCKDB_NOT_INSTALLED", "DATASET_CHANGED",
               "QUERY_NOT_DECLARED", "INVALID_INPUT", "INVALID_RESULT", "RESULT_TOO_LARGE"}


def encoded(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def fail(code):
    print(encoded({"ok": False, "error": code}))
    return 1


def read_config(path):
    with path.open("rb") as handle:
        data = handle.read(1048577)
    if len(data) > 1048576:
        raise ValueError("CONFIG_INVALID")
    config = json.loads(data.decode("utf-8"))
    if not isinstance(config, dict) or config.get("schema") != SCHEMA:
        raise ValueError("CONFIG_INVALID")
    base = Path(config["baseDirectory"])
    if not base.is_absolute() or str(base.resolve()) != str(base) or not base.is_dir():
        raise ValueError("CONFIG_INVALID")
    files = config["files"]
    if not isinstance(files, list) or len(files) > 33:
        raise ValueError("CONFIG_INVALID")
    for item in files:
        local = Path(item["path"])
        if not local.is_absolute() or not local.is_relative_to(base) or str(local.resolve()) != str(local):
            raise ValueError("CONFIG_INVALID")
    approved = config["parquetFiles"]
    database = config["database"]
    if not isinstance(approved, list) or len(approved) > 32 or any(not file.lower().endswith(".parquet") for file in approved):
        raise ValueError("CONFIG_INVALID")
    required = set(approved) | ({database} if database != ":memory:" else set())
    if required != {item["path"] for item in files}:
        raise ValueError("CONFIG_INVALID")
    queries = config["queries"]
    if not isinstance(queries, dict) or not 1 <= len(queries) <= 32:
        raise ValueError("CONFIG_INVALID")
    for name, query in queries.items():
        if not NAME.fullmatch(name) or not isinstance(query, dict) or not isinstance(query.get("sql"), str):
            raise ValueError("CONFIG_INVALID")
        columns = query["columns"]
        if not isinstance(columns, list) or not 1 <= len(columns) <= 64 or len(set(columns)) != len(columns) or any(not NAME.fullmatch(col) for col in columns):
            raise ValueError("CONFIG_INVALID")
        if not isinstance(query["parameters"], dict) or len(query["parameters"]) > 32 or any(not NAME.fullmatch(key) for key in query["parameters"]):
            raise ValueError("CONFIG_INVALID")
        if type(query["maxRows"]) is not int or not 1 <= query["maxRows"] <= 1000 or type(query["maxBytes"]) is not int or not 1024 <= query["maxBytes"] <= 917504:
            raise ValueError("CONFIG_INVALID")
    options = config["options"]
    if type(options["memoryLimitMb"]) is not int or not 32 <= options["memoryLimitMb"] <= 1024 or type(options["threads"]) is not int or not 1 <= options["threads"] <= 4:
        raise ValueError("CONFIG_INVALID")
    return config


def unchanged(config):
    for item in config["files"]:
        path = Path(item["path"])
        try:
            info = path.lstat()
            same = path.is_file() and not path.is_symlink() and str(path.resolve()) == str(path) and (
                str(info.st_size), str(info.st_mtime_ns), str(info.st_ino)) == (
                item["size"], item["modifiedNs"], item["inode"])
        except OSError:
            same = False
        if not same:
            raise ValueError("DATASET_CHANGED")


def connect(config):
    try:
        import duckdb
    except ImportError:
        raise RuntimeError("DUCKDB_NOT_INSTALLED")
    options = config["options"]
    connection = duckdb.connect(config["database"], read_only=config["database"] != ":memory:", config={
        "allow_unsigned_extensions": "false", "autoinstall_known_extensions": "false",
        "autoload_known_extensions": "false", "allow_community_extensions": "false",
        "allow_persistent_secrets": "false", "memory_limit": str(options["memoryLimitMb"]) + "MB",
        "threads": str(options["threads"]),
    })
    # Only local, individually declared Parquet files remain available after this.
    literals = ",".join("'" + value.replace("'", "''") + "'" for value in config["parquetFiles"])
    connection.execute("SET allowed_paths = [" + literals + "]")
    connection.execute("SET enable_external_access = false")
    connection.execute("SET lock_configuration = true")
    return connection, duckdb.__version__


def decode(value, spec):
    if value is None:
        if spec.get("nullable") is True:
            return None
        raise ValueError("INVALID_INPUT")
    kind = spec["type"]
    if kind == "string" and isinstance(value, str) and len(value) <= 65536:
        return value
    if kind == "integer" and isinstance(value, str) and re.fullmatch(r"(?:0|-[1-9]\d*|[1-9]\d*)", value):
        number = int(value)
        if -(2**63) <= number <= 2**63 - 1:
            return number
    if kind == "number" and isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value):
        return value
    if kind == "boolean" and isinstance(value, bool):
        return value
    raise ValueError("INVALID_INPUT")


def sample(spec):
    value = spec.get("default", spec.get("enum", [{"string": "", "integer": "0", "number": 0, "boolean": False}[spec["type"]]])[0])
    if value is None:
        return None
    if spec["type"] == "integer":
        return int(value)
    if spec["type"] == "number":
        return float(value)
    if spec["type"] == "boolean":
        return value is True or value == "true"
    return value


def encode(value):
    if value is None or isinstance(value, (bool, str)):
        return value
    if isinstance(value, (int, decimal.Decimal)):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("INVALID_RESULT")
        return value
    if isinstance(value, (bytes, bytearray, memoryview)):
        return {"$base64": base64.b64encode(bytes(value)).decode("ascii")}
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, (list, tuple)):
        return [encode(item) for item in value]
    if isinstance(value, dict):
        return {str(key): encode(item) for key, item in value.items()}
    return str(value)


def projection(query, limit):
    columns = ",".join('"' + col + '"' for col in query["columns"])
    return "SELECT " + columns + " FROM (\n" + query["sql"] + "\n) AS sf30_approved LIMIT " + str(limit)


def bounded_statement(query):
    projected = projection(query, query["maxRows"] + 1)
    # Suppress oversized rows inside DuckDB before Python receives their values.
    # The complete public JSON is separately budgeted after exact value encoding.
    checked = "SELECT p.*, octet_length(encode(CAST(to_json(p) AS VARCHAR))) AS __sf30_bytes FROM (" + projected + ") AS p"
    columns = ",".join('CASE WHEN __sf30_bytes <= ' + str(query["maxBytes"]) + ' THEN "' + col + '" ELSE NULL END AS "' + col + '"' for col in query["columns"])
    return "SELECT " + columns + ",__sf30_bytes > " + str(query["maxBytes"]) + " AS __sf30_large FROM (" + checked + ") AS guarded"


def run(source, name, checking):
    config = read_config(source)
    unchanged(config)
    os.chdir(config["baseDirectory"])
    connection, version = connect(config)
    try:
        if checking:
            types = {}
            for query_name, query in config["queries"].items():
                values = {key: sample(spec) for key, spec in query["parameters"].items()}
                result = connection.execute(projection(query, 0), values)
                types[query_name] = {str(item[0]): str(item[1]) for item in result.description}
            unchanged(config)
            print(encoded({"ok": True, "schema": SCHEMA, "engineVersion": version, "columnTypes": types}))
            return 0
        if name not in config["queries"]:
            return fail("QUERY_NOT_DECLARED")
        raw = sys.stdin.buffer.read(262145)
        if len(raw) > 262144:
            return fail("INVALID_INPUT")
        request = json.loads(raw.decode("utf-8"))
        query = config["queries"][name]
        if not isinstance(request, dict) or set(request) != {"values"} or not isinstance(request["values"], dict) or set(request["values"]) != set(query["parameters"]):
            return fail("INVALID_INPUT")
        values = {key: decode(request["values"][key], spec) for key, spec in query["parameters"].items()}
        cursor = connection.execute(bounded_statement(query), values)
        rows, row_bytes, truncated = [], 0, False
        while True:
            record = cursor.fetchone()
            if record is None:
                break
            if len(rows) == query["maxRows"]:
                truncated = True
                break
            if record[-1]:
                return fail("RESULT_TOO_LARGE")
            row = {column: encode(cell) for column, cell in zip(query["columns"], record[:-1])}
            row_bytes += len(encoded(row).encode("utf-8"))
            if row_bytes > query["maxBytes"]:
                return fail("RESULT_TOO_LARGE")
            rows.append(row)
        unchanged(config)
        payload = {"schema": "stellar-forge.duckdb-result.v1", "query": name,
                   "columns": query["columns"], "rows": rows, "rowCount": len(rows), "truncated": truncated,
                   "encodings": {"integer": "decimal-string", "decimal": "decimal-string", "blob": "$base64", "date": "iso8601"}}
        output = encoded({"ok": True, "payload": payload})
        if len(output.encode("utf-8")) > query["maxBytes"]:
            return fail("RESULT_TOO_LARGE")
        print(output)
        return 0
    finally:
        connection.close()


def main():
    parser = argparse.ArgumentParser(description="Packaged SF30 DuckDB worker; use the Node source CLI")
    parser.add_argument("--source", required=True)
    choice = parser.add_mutually_exclusive_group(required=True)
    choice.add_argument("--query")
    choice.add_argument("--check", action="store_true")
    args = parser.parse_args()
    try:
        return run(Path(args.source).resolve(), args.query, args.check)
    except Exception as issue:
        return fail(str(issue) if str(issue) in SAFE_ERRORS else "DUCKDB_QUERY_UNAVAILABLE")


if __name__ == "__main__":
    raise SystemExit(main())

"""MIT. Trusted local merchant functions, private parent protocol on descriptor 3."""
import asyncio
import base64
import contextvars
import importlib.util
import inspect
import hashlib
import json
import math
import os
from pathlib import Path
import sys

PROTOCOL = os.fdopen(3, 'wb', buffering=0)
MAX_LINE = 1100000


def send(value):
    PROTOCOL.write(json.dumps(value, separators=(',', ':'), allow_nan=False).encode('utf-8') + b'\n')


async def read(reader):
    # The same worker loop remains active while waiting for the next invocation,
    # so application-owned connection tasks are not frozen between requests.
    line = await reader.readline()
    if not line:
        return None
    if len(line) > MAX_LINE or not line.endswith(b'\n'):
        raise ValueError('protocol')
    return json.loads(line, parse_constant=lambda _: (_ for _ in ()).throw(ValueError('nonfinite')))


def json_body(value, max_bytes):
    # Preserve interoperable JSON numbers. Explicitly return decimal strings for
    # larger Python integers rather than silently rounding them in JavaScript.
    stack = [(value, 0)]
    count = 0
    while stack:
        item, depth = stack.pop()
        count += 1
        if count > 100000 or depth > 32:
            raise ValueError('complexity')
        if item is None or type(item) in (str, bool):
            continue
        if type(item) is int:
            if abs(item) > 9007199254740991:
                raise ValueError('integer')
        elif type(item) is float:
            if not math.isfinite(item):
                raise ValueError('nonfinite')
        elif type(item) is list:
            stack.extend((child, depth + 1) for child in item)
        elif type(item) is dict:
            if any(type(key) is not str for key in item):
                raise ValueError('keys')
            stack.extend((child, depth + 1) for child in item.values())
        else:
            raise ValueError('json_type')
    chunks = []
    size = 0
    for chunk in json.JSONEncoder(ensure_ascii=False, allow_nan=False, separators=(',', ':')).iterencode(value):
        encoded = chunk.encode('utf-8')
        size += len(encoded)
        if size > max_bytes:
            raise ValueError('size')
        chunks.append(encoded)
    return b''.join(chunks)


async def attach_input():
    reader = asyncio.StreamReader(limit=MAX_LINE)
    transport, _ = await asyncio.get_running_loop().connect_read_pipe(
        lambda: asyncio.StreamReaderProtocol(reader), sys.stdin.buffer)
    return reader, transport


async def await_value(value):
    return await value


def invoke(runner, function, *args, context):
    # Call synchronous functions outside a running event loop, as before. Async
    # results use one persistent loop, including startup and shutdown hooks.
    asyncio.set_event_loop(runner.get_loop())
    result = context.run(function, *args)
    return runner.run(await_value(result), context=context) if inspect.isawaitable(result) else result


def hook(module, name):
    if name is None:
        return None
    function = getattr(module, name)
    if not callable(function):
        raise ValueError('hook_callable')
    inspect.signature(function).bind()
    return function


def main():
    # Merchant imports and prints never share the protocol or public server log.
    sys.stdout = open(os.devnull, 'w', encoding='utf-8')
    sys.stderr = open(os.devnull, 'w', encoding='utf-8')
    runner = asyncio.Runner()
    application_context = contextvars.copy_context()
    transport, shutdown = None, None
    ready, cleanup = False, False
    stop_code = None
    try:
        reader, transport = runner.run(attach_input())
        initial = runner.run(read(reader))
        path = Path(sys.argv[1]).resolve(strict=True)
        source = path.read_bytes()
        if len(source) > 2097152 or hashlib.sha256(source).hexdigest() != initial['applicationSha256']:
            raise ValueError('application_changed')
        sys.path.insert(0, str(path.parent))
        spec = importlib.util.spec_from_file_location('_sf30_merchant', path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        exec(compile(source, str(path), 'exec'), module.__dict__)
        definitions = initial['functions']
        functions = {}
        for name in definitions:
            function = getattr(module, name)
            if not callable(function):
                raise ValueError('callable')
            # Exactly one positional input object; reject mismatched bindings at boot.
            inspect.signature(function).bind({})
            functions[name] = function
        lifecycle = initial.get('lifecycle', {})
        startup = hook(module, lifecycle.get('startup'))
        shutdown = hook(module, lifecycle.get('shutdown'))
        # Cleanup can release partially initialized resources after startup fails.
        # A parent-enforced hard deadline can still terminate this worker.
        cleanup = True
        if startup is not None:
            invoke(runner, startup, context=application_context)
        send({'type': 'ready'})
        ready = True
        while True:
            request = runner.run(read(reader))
            if request is None:
                break
            request_id, name = request['id'], request['name']
            if type(request_id) is not int or name not in functions or type(request['input']) is not dict:
                raise ValueError('request')
            try:
                # Reuse initialized resources, not another buyer's ContextVars.
                result = invoke(runner, functions[name], request['input'], context=application_context.copy())
            except BaseException:
                send({'type': 'error', 'id': request_id, 'code': 'PYTHON_FUNCTION_FAILED'})
                continue
            try:
                definition = definitions[name]
                if definition['output']['format'] == 'bytes':
                    if not isinstance(result, (bytes, bytearray)):
                        raise ValueError('bytes_required')
                    if len(result) > definition['maxOutputBytes']:
                        raise ValueError('size')
                    body = bytes(result)
                else:
                    body = json_body(result, definition['maxOutputBytes'])
                send({'type': 'result', 'id': request_id, 'body': base64.b64encode(body).decode('ascii')})
            except BaseException:
                send({'type': 'error', 'id': request_id, 'code': 'PYTHON_OUTPUT_REJECTED'})
    except BaseException:
        stop_code = 'PYTHON_PROTOCOL_REJECTED' if ready else 'PYTHON_APPLICATION_UNAVAILABLE'
    finally:
        if cleanup and shutdown is not None:
            try:
                invoke(runner, shutdown, context=application_context)
            except BaseException:
                stop_code = stop_code or 'PYTHON_SHUTDOWN_FAILED'
        if transport is not None:
            transport.close()
        try:
            # Cancels remaining application tasks and closes async generators
            # before acknowledging exit. Parent timeout covers stubborn cleanup.
            runner.close()
        except BaseException:
            stop_code = stop_code or 'PYTHON_RUNTIME_CLOSE_FAILED'
    if not ready:
        send({'type': 'startup-error', 'code': 'PYTHON_APPLICATION_UNAVAILABLE'})
        return 1
