    sourceBundles:manifest.sourceBundles.map(({bundleId,manifestSha256,editionIds,caseRevisions,archive})=>
      ({bundleId,manifestSha256,editionIds,caseRevisions,archive})),caseHistory:manifest.caseHistory,
