    need(reopened.sourceSignature===packet.sourceSignature&&reopened.captureId===packet.captureId,
      'GRANTS_CAPTURE_IMPORT_IDENTITY_MISMATCH');
    return reopened;
  }finally{await release();}
}

// MIT. Local operator interface over the maintained PostgreSQL/dataset engines.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fault } from './files.mjs';
import { openPostgresSchedule } from './schedule.mjs';

async function body(req) {
  if (!/^application\/json(?:\s*;|$)/i.test(req.headers['content-type'] ?? ''))
    throw fault('JSON_REQUIRED', 'Send application/json.', 415);
  const chunks = []; let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 262144) throw fault('REQUEST_TOO_LARGE', 'The request exceeds 256 KiB.', 413);
    chunks.push(chunk);
  }
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))); }
  catch { throw fault('JSON_INVALID'); }
}
export async function startPostgresPublisherServer({ publisher, port = 8442, extension = null,
  schedule: borrowedSchedule = null, ownsPublisher = true } = {}) {
