      if (typeof asset.path !== 'string' || !/^\/[A-Za-z0-9_/-]+\.(mjs|css)$/.test(asset.path) ||
          assets.has(asset.path) || !Buffer.isBuffer(asset.bytes) || typeof asset.type !== 'string')
