    switch (operation) {
      case 'merchant_accounting_qbo_connection':
        if (this.qboOAuth) await this.qboOAuth.connection();
        return { ...this.qbo.connection(), configured: Boolean(this.definition.qbo) };
      case 'merchant_accounting_qbo_company_fetch': {
