  const record=()=>{field();records.push({rowNumber:records.length+1,lineNumber:startLine,values});values=[];check(records.length<=MAX_RETURN_ROWS+1,'TOO_MANY_RETURN_ROWS','The CSV exceeds '+MAX_RETURN_ROWS+' return rows.');};
