        try {finish(null,JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(chunks,size))));}
        catch {finish(failure());}
      });
    });
    request.once('error',()=>finish(failure()));
    timer=setTimeout(()=>{request.destroy();finish(failure());},5000);
    request.end();
