  for (const row of eventPage?.rows ?? []) {
    if (row.deliveryState !== 'EXHAUSTED' || selectedEvents.has(row.event.id) || selectedEvents.size >= 100) continue;
    selectedEvents.set(row.event.id, {row, needsReview:false}); ++added;
  }
